import path from "node:path";
import { db } from "@/lib/db";
import type { IAssetGenerationMetadata } from "@/app/interfaces/comfy-input";

export interface IAssetListItem {
    id: number;
    title: string | null;
    promptText: string | null;
    oldimg: string | null;
    fileName: string;
    relativePath: string;
    mediaType: "image" | "video" | "model";
    workflowType: "text" | "line" | "magic" | null;
    promptId: string | null;
    thumbnailPath: string | null;
    createdAt: string;
}

export interface IAlbumListItem {
    id: number;
    name: string;
    thumbnailPath: string | null;
    assetCount: number;
    createdAt: string;
}

interface IComfyOutputFileRecord {
    filename?: string;
    subfolder?: string;
}

interface IPersistGeneratedAssetsArgs {
    outputFiles: IComfyOutputFileRecord[];
    promptId: string;
    oldImagePath?: string;
    metadata?: IAssetGenerationMetadata;
}

export class AssetLibraryService {
    public listAlbums(): IAlbumListItem[] {
        this.ensureAlbumTables();

        const statement = db.prepare(`
            SELECT
                albums.id,
                albums.name,
                albums.created_at AS createdAt,
                (
                    SELECT COUNT(*)
                    FROM assets
                    WHERE assets.album_id = albums.id
                        AND assets.deleted_at IS NULL
                ) AS assetCount,
                (
                    SELECT assets.thumbnail_path
                    FROM assets
                    WHERE assets.album_id = albums.id
                        AND assets.deleted_at IS NULL
                    ORDER BY datetime(assets.created_at) DESC, assets.id DESC
                    LIMIT 1
                ) AS thumbnailPath
            FROM albums
            ORDER BY datetime(albums.created_at) DESC, albums.id DESC
        `);

        return statement.all() as IAlbumListItem[];
    }

    public createAlbum(name: string): IAlbumListItem {
        this.ensureAlbumTables();

        const normalizedName = name.trim();
        if (!normalizedName) {
            throw new Error("作品册名称不能为空");
        }

        if (normalizedName.length > 20) {
            throw new Error("作品册名称不能超过20个字符");
        }

        const insert = db.prepare(`
            INSERT INTO albums (name)
            VALUES (@name)
        `);

        const result = insert.run({ name: normalizedName });

        const selectById = db.prepare(`
            SELECT
                albums.id,
                albums.name,
                albums.created_at AS createdAt,
                0 AS assetCount,
                NULL AS thumbnailPath
            FROM albums
            WHERE albums.id = @id
            LIMIT 1
        `);

        return selectById.get({ id: result.lastInsertRowid }) as IAlbumListItem;
    }

    public persistGeneratedAssets(args: IPersistGeneratedAssetsArgs): void {
        const { outputFiles, promptId, oldImagePath, metadata } = args;

        if (!metadata?.mediaType || outputFiles.length === 0) {
            return;
        }

        const insertAsset = db.prepare(`
            INSERT INTO assets (
                title,
                prompt_text,
                oldimg,
                file_name,
                relative_path,
                media_type,
                workflow_type,
                prompt_id,
                thumbnail_path,
                album_id
            ) VALUES (
                @title,
                @prompt_text,
                @oldimg,
                @file_name,
                @relative_path,
                @media_type,
                @workflow_type,
                @prompt_id,
                @thumbnail_path,
                NULL
            )
        `);

        const insertMany = db.transaction((files: IComfyOutputFileRecord[]) => {
            for (const file of files) {
                const fileName = file.filename?.trim();
                if (!fileName) {
                    continue;
                }

                const relativePath = this.buildRelativePath(file);
                const thumbnailPath = metadata.mediaType === "image" ? relativePath : null;
                // Derive title from the actual filename (already deduplicated on disk) so DB title always matches file name
                const persistedTitle = path.parse(fileName).name || null;

                insertAsset.run({
                    title: persistedTitle,
                    prompt_text: metadata.promptText?.trim() || null,
                    oldimg: oldImagePath || null,
                    file_name: fileName,
                    relative_path: relativePath,
                    media_type: metadata.mediaType,
                    workflow_type: metadata.mediaType === "image" ? metadata.workflowType || null : null,
                    prompt_id: promptId,
                    thumbnail_path: thumbnailPath,
                });
            }
        });

        insertMany(outputFiles);
    }

    private buildUniqueAssetTitle(baseTitle: string): string {
        const cleanBaseTitle = baseTitle.trim();
        if (!cleanBaseTitle) {
            return baseTitle;
        }

        const existsByTitle = db.prepare(`
            SELECT 1
            FROM assets
            WHERE title = @title
                AND deleted_at IS NULL
            LIMIT 1
        `);

        let candidate = cleanBaseTitle;
        let suffix = 1;

        while (existsByTitle.get({ title: candidate })) {
            candidate = `${cleanBaseTitle}_${suffix}`;
            suffix += 1;
        }

        return candidate;
    }

    public listAssets(args?: {
        mediaType?: "image" | "video" | "model";
        search?: string;
        albumId?: string;
    }): IAssetListItem[] {
        this.ensureAlbumTables();

        const conditions: string[] = ["assets.deleted_at IS NULL"];
        const queryParams: Record<string, string | number> = {};

        if (args?.albumId === "default") {
            conditions.push("assets.album_id IS NULL");
        } else if (args?.albumId && /^\d+$/.test(args.albumId)) {
            conditions.push("assets.album_id = @albumId");
            queryParams.albumId = Number(args.albumId);
        }

        if (args?.mediaType) {
            conditions.push("assets.media_type = @mediaType");
            queryParams.mediaType = args.mediaType;
        }

        if (args?.search?.trim()) {
            conditions.push("(COALESCE(assets.title, '') LIKE @search OR COALESCE(assets.prompt_text, '') LIKE @search OR COALESCE(assets.file_name, '') LIKE @search)");
            queryParams.search = `%${args.search.trim()}%`;
        }

        const statement = db.prepare(`
            SELECT
                id,
                title,
                prompt_text AS promptText,
                oldimg,
                file_name AS fileName,
                relative_path AS relativePath,
                media_type AS mediaType,
                workflow_type AS workflowType,
                prompt_id AS promptId,
                thumbnail_path AS thumbnailPath,
                created_at AS createdAt
            FROM assets
            WHERE ${conditions.join(" AND ")}
            ORDER BY datetime(created_at) DESC, id DESC
        `);

        return statement.all(queryParams) as IAssetListItem[];
    }

    public moveAssetsToAlbum(assetIds: number[], albumId: number | null): number {
        this.ensureAlbumTables();

        if (!assetIds.length) {
            return 0;
        }

        if (albumId !== null) {
            const albumExists = db.prepare(`
                SELECT 1
                FROM albums
                WHERE id = @albumId
                LIMIT 1
            `).get({ albumId });

            if (!albumExists) {
                throw new Error("目标作品册不存在");
            }
        }

        const moveAsset = db.prepare(`
            UPDATE assets
            SET album_id = @albumId
            WHERE id = @assetId
                AND deleted_at IS NULL
        `);

        const tx = db.transaction((ids: number[]) => {
            let movedCount = 0;

            for (const assetId of ids) {
                const result = moveAsset.run({ assetId, albumId });
                movedCount += result.changes;
            }

            return movedCount;
        });

        return tx(assetIds);
    }

    public softDeleteAssets(assetIds: number[]): number {
        this.ensureAlbumTables();

        if (!assetIds.length) {
            return 0;
        }

        const softDeleteAsset = db.prepare(`
            UPDATE assets
            SET deleted_at = CURRENT_TIMESTAMP,
                album_id = NULL
            WHERE id = @assetId
                AND deleted_at IS NULL
        `);

        const tx = db.transaction((ids: number[]) => {
            let deletedCount = 0;

            for (const assetId of ids) {
                const result = softDeleteAsset.run({ assetId });
                deletedCount += result.changes;
            }

            return deletedCount;
        });

        return tx(assetIds);
    }

    private buildRelativePath(file: IComfyOutputFileRecord): string {
        const fileName = file.filename?.trim() || "";
        const subfolder = file.subfolder?.trim();

        if (!subfolder) {
            return fileName;
        }

        return `${subfolder}/${fileName}`;
    }

    private ensureAlbumTables(): void {
        db.exec(`
            CREATE TABLE IF NOT EXISTS albums (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                cover_asset_id INTEGER,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );
        `);

        const columns = db.prepare("PRAGMA table_info(assets)").all() as Array<{ name: string }>;
        const hasAlbumId = columns.some((column) => column.name === "album_id");

        if (!hasAlbumId) {
            db.exec(`
                ALTER TABLE assets ADD COLUMN album_id INTEGER;
            `);
        }

        db.exec("CREATE INDEX IF NOT EXISTS idx_assets_album_id ON assets(album_id);");
    }
}